// План specs/technicians-sms.md 2.1 (кейс #63ed24; рядом #de116e). PROD, admin, компания «test», десктоп 1440, EN.
// @prod-safe: SMS не уходит — message-technicians перехвачен context.route (фейковый 200), send-sms/assignment-notices обрываются,
// service worker отключён; тест падает, если хоть один POST ушёл в сеть (expectNothingSent). Отмечаются только QA-F5 tech и QA-Tech Gamma.
// Источник: «מה רצוי» — тост результата не закрывает кнопки страницы (показан в другом месте / как остальные сообщения),
// «Text selected» и «New Technician» кликабельны, пока тост показан. Комментарий программиста: на десктопе тосты в правом нижнем углу.
// Факты 17.11: тост внизу справа, кнопки кликабельны. Мобильный (тост под шапкой, #58) — отдельный кейс, здесь не проверяется.
import { test, expect } from '@playwright/test';
import {
  ADMIN_STATE, L, expectNothingSent, interceptSending, openTechnicians, resultCards, selectQaTechs, sendText,
} from './technicians-sms-helpers';

test.use({ storageState: ADMIN_STATE, serviceWorkers: 'block', viewport: { width: 1440, height: 900 } });

test.describe('Technicians: result toast does not cover the page buttons (#63ed24)', () => {
  test('After Send the toast is in the bottom-right corner; "Text selected" and "New Technician" stay clickable while it is shown #63ed24 @desktop @prod-safe', async ({ page, context }) => {
    const guard = await interceptSending(context);
    await openTechnicians(page, 'en');
    await selectQaTechs(page, 'en');
    await sendText(page, 'en', 'QA-AUTO 63ed24');

    await expect(page.getByText(L.en.result).first()).toBeVisible({ timeout: 15_000 });
    const { innerWidth, cards } = await resultCards(page, 'en');
    expect(cards, 'на экране один тост результата').toHaveLength(1);
    const card = cards[0];
    const innerHeight = page.viewportSize()!.height;
    expect(card.left, 'тост в правой половине экрана').toBeGreaterThan(innerWidth / 2);
    expect(card.right, 'тост не выходит за правый край').toBeLessThanOrEqual(innerWidth + 0.5);
    expect(card.top, 'тост в нижней половине экрана (не над кнопками в шапке страницы)').toBeGreaterThan(innerHeight / 2);

    // Кнопки сверху не перекрыты тостом
    const textSelected = page.getByRole('button', { name: L.en.textSelected }).first();
    const newTech = page.getByRole('button', { name: /New Technician/ }).first();
    for (const [name, btn] of [['Text selected', textSelected], ['New Technician', newTech]] as const) {
      const b = (await btn.boundingBox())!;
      const overlap = !(b.x + b.width <= card.left || b.x >= card.right || b.y + b.height <= card.top || b.y >= card.bottom);
      expect(overlap, `кнопка «${name}» не под тостом`).toBe(false);
    }

    // Пока тост виден — «New Technician» срабатывает (открывается окно)
    await newTech.click();
    await expect(page.getByRole('dialog')).toBeVisible();
    expectNothingSent(guard, 1);
  });
});
